def conv(L):
    out=[]
    for i,(h,e,c,w,x,p,peg) in enumerate(L,1):
        out.append({"id":f"d{i}","tipo":"mc","habilidade":h,"enunciado":e,"resposta":c,"alternativas":[c]+[a for a,_ in w],"explicacao":x,"tutor":{"alternativas":{a:b for a,b in w},"pontos":p,"pegadinha":peg}})
    return out
sql=""
for m,t,L in [('mt','Diagnóstico de largada: Matemática',MT),('pt','Diagnóstico de largada: Português',PT),('en','Diagnóstico de largada: Inglês',EN)]:
    js=json.dumps(conv(L),ensure_ascii=False); assert '$j$' not in js
    sql+=f"""insert into materiais (turma_id, autor, materia, titulo, status, questoes, publicado_em)
select t.id, (select tp.professor_id from turma_professores tp where tp.turma_id = t.id limit 1), '{m}', '{t}', 'publicado', $j${js}$j$::jsonb, now()
from turmas t join escolas e on e.id = t.escola_id
where e.codigo = 'PILOTO' and t.nome = '6º ano A'
  and not exists (select 1 from materiais x where x.turma_id = t.id and x.titulo = '{t}');
"""
open('/home/claude/app/supabase/migrations/004_diagnostico_largada.sql','w').write(sql)
print('ok', len(MT),len(PT),len(EN))

